{
  "claim_id": "1dcf2bdd-dd23-413c-96a7-b5d695bb0a31",
  "text": "Stable microscopic black holes produced at the LHC would endanger Earth.",
  "claim_type": "empirical_derived",
  "lifecycle_state": "active",
